/** 根据 emoji 生成 SVG Data URI 封面图 */
export function generateCoverSVG(emoji: string): string {
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#FFF8F0" rx="12"/><text x="100" y="115" text-anchor="middle" font-size="80">' + emoji + '</text></svg>';
  const bytes = new TextEncoder().encode(svg);
  const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join('');
  return 'data:image/svg+xml;base64,' + btoa(binary);
}

